using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Swashbuckle.AspNetCore.Annotations;using GraphApi.Models.NTF.TiposNotificacion;using GraphApi.Services.NTF.TiposNotificacion;namespace GraphApi.Controllers.NTF.TiposNotificacion{    /// <summary>    /// Gestión de TiposNotificacions: consulta, creación, actualización y borrado.    /// </summary>    [ApiController]    [Authorize]    [Route("NTF/[controller]")]    [Produces("application/json")]    [SwaggerTag("Operaciones sobre TiposNotificacions")]    public class TiposNotificacionController : Controller    {        private readonly ITiposNotificacionService _objService;        public TiposNotificacionController(ITiposNotificacionService objService)        {            _objService = objService;        }        /// <summary>        /// Obtiene todos los TiposNotificacions, con filtros opcionales.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="tipoNotificacionID">TipoNotificacionID</param>        /// <param name="tipoNotiicfacion">TipoNotiicfacion</param>        /// <param name="bEliminado">bEliminado</param>        /// <returns>Listado de TiposNotificacions</returns>        [HttpGet]        [SwaggerOperation(            Summary = "Listar TiposNotificacions",            Description = "Devuelve TiposNotificacions aplicando filtros opcionales."        )]        [ProducesResponseType(typeof(IEnumerable<clReadTiposNotificacion>), StatusCodes.Status200OK)]        public async Task<ActionResult<IEnumerable<clReadTiposNotificacion>>> GetAll(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromQuery] int? tipoNotificacionID,            [FromQuery] string? tipoNotiicfacion,            [FromQuery] bool? bEliminado,            [FromQuery] string? columnNames)        {            var vList = await _objService.GetTiposNotificacionsDynamic(                tipoNotificacionID,                 tipoNotiicfacion,                 bEliminado,                 columnNames, nUserId, sWindowName);              return vList.Count()==0  ? NotFound() :  Ok(vList);        }        /// <summary>        /// Crea un nuevo TiposNotificacion.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Datos del TiposNotificacion a crear.</param>        /// <returns>El TiposNotificacion recién creado.</returns>        [HttpPost]        [SwaggerOperation(            Summary = "Crear TiposNotificacions",            Description = "Inserta un nuevo TiposNotificacion en la base de datos."        )]        [ProducesResponseType(typeof(clReadTiposNotificacion), StatusCodes.Status201Created)]        public async Task<ActionResult<clReadTiposNotificacion>> Create(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clCreateTiposNotificacion objInput)        {            var vCreated = await _objService.CreateTiposNotificacion(objInput, nUserId, sWindowName);            return vCreated is null ? NoContent() : vCreated;        }        /// <summary>        /// Actualización parcial de TiposNotificacion.        /// </summary>        /// <param name="userId">Id de usuario (header "UserID").</param>        /// <param name="windowName">Nombre de la aplicación (header "WindowName").</param>        /// <param name="input">Campos a actualizar y el ID del TiposNotificacion.</param>        /// <returns>El TiposNotificacion actualizado.</returns>        [HttpPatch]        [SwaggerOperation(            Summary = "Actualizar TiposNotificacions",            Description = "Actualiza uno o varios campos de TiposNotificacion existente."        )]        [ProducesResponseType(typeof(clReadTiposNotificacion), StatusCodes.Status200OK)]        public async Task<ActionResult<clReadTiposNotificacion>> Patch(            [FromHeader(Name = "UserID")] int nUserId,            [FromHeader(Name = "WindowName")] string sWindowName,            [FromBody] clUpdateTiposNotificacion objInput)        {            var vUpdated = await _objService.UpdateTiposNotificacion(objInput, nUserId, sWindowName);            return vUpdated is null ? NotFound() : Ok(vUpdated);        }        /// <summary>        /// Elimina un TiposNotificacion por su ID.        /// </summary>        [HttpDelete("{nTiposNotificacionID:int}")]        [SwaggerOperation(            Summary = "Eliminar TiposNotificacion",            Description = "Borra un TiposNotificacion si existe."        )]        [ProducesResponseType(StatusCodes.Status204NoContent)]        public async Task<IActionResult> Delete(int nTiposNotificacionID)        {            var success = await _objService.DeleteTiposNotificacion(nTiposNotificacionID);            return success ? NoContent() : NotFound();        }    }}